// Freeze one common price book for every window, rather than compare historical
// costs priced under different rules. Initialization only writes bounded metadata.
func (s *Service) normalizationRules(ctx context.Context) (NormalizationRules, error) {
	var rules NormalizationRules
	var raw string
	err := s.db.QueryRowContext(ctx, `SELECT payload FROM analytics_normalization_rules WHERE id=?`, normalizationRuleID).Scan(&raw)
	if err == nil {
		err = json.Unmarshal([]byte(raw), &rules)
		return rules, err
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return rules, err
	}
	prices, err := s.store.LoadModelPrices(ctx)
	if err != nil {
		return rules, err
	}
	rules = NormalizationRules{ID: normalizationRuleID, Captured: s.at, Prices: prices}
	if _, err = s.db.ExecContext(ctx, `INSERT OR IGNORE INTO analytics_normalization_rules VALUES(?,?,?)`, rules.ID, rules.Captured, string(encode(rules))); err != nil {
		return rules, err
	}

	return s.normalizationRules(ctx)
}

